<?php require 'config.php';$u=require_login();require_innovations();page_start('Milestones',$u);heading('PROGRESS, NOT PERFECTION','Every small step counts.','Your milestones reflect real learning and contributions. No leaderboard pressure.');$s=learning_streak((int)$u['id']);$completed=(int)one('SELECT COUNT(*) n FROM progress WHERE user_id=?',[$u['id']])['n'];$approved=(int)one("SELECT COUNT(*) n FROM challenge_submissions WHERE user_id=? AND status='approved'",[$u['id']])['n'];$projects=(int)one('SELECT COUNT(*) n FROM projects WHERE user_id=?',[$u['id']])['n'];$topics=(int)one('SELECT COUNT(*) n FROM topics WHERE user_id=?',[$u['id']])['n']; ?>
<div class="stats"><div><strong><?=$s['current']?></strong><span>Current streak · days</span></div><div><strong><?=$s['best']?></strong><span>Best streak · days</span></div><div><strong><?=$s['days']?></strong><span>Meaningful activity days</span></div><div><strong><?=$approved?></strong><span>Approved challenge solutions</span></div></div>
<section class="card"><h2>A rhythm you can return to.</h2><p>A learning day is recorded when you complete a resource, submit a challenge, publish a project, start/reply to a discussion or leave project feedback. Multiple actions on the same Africa/Freetown date count as one day. Visits and reactions do not count. Your current streak stays active through yesterday; missing a full day resets it. Historical activity before the upgrade is not invented.</p><div class="activity-calendar"><?php $dates=array_column(rows('SELECT activity_date FROM activity_days WHERE user_id=? AND activity_date>=?',[$u['id'],date('Y-m-d',strtotime('-27 days'))]),'activity_date');for($n=27;$n>=0;$n--):$day=date('Y-m-d',strtotime('-'.$n.' days'));?><span class="activity-cell <?=in_array($day,$dates)?'earned':''?>" title="<?=e($day)?>" aria-label="<?=e($day.(in_array($day,$dates)?': activity recorded':': no activity'))?>"><?=date('j',strtotime($day))?></span><?php endfor;?></div><p class="meta">Last 28 days · highlighted dates have recorded activity.</p></section>
<div class="grid"><?php foreach([
 ['First spark','Complete one learning resource',$completed>=1],['Curious explorer','Complete three learning resources',$completed>=3],['Conversation starter','Publish a discussion topic',$topics>=1],['Community maker','Publish a project',$projects>=1],['Challenge builder','Receive one manual challenge approval',$approved>=1],['Three-day rhythm','Record a three-day learning streak',$s['best']>=3],['Seven-day momentum','Record a seven-day learning streak',$s['best']>=7]
] as [$name,$rule,$earned]):?><article class="card achievement <?=$earned?'earned':'locked'?>"><div class="achievement-symbol" aria-hidden="true"><?=$earned?'✦':'◇'?></div><span class="badge"><?=$earned?'Earned':'Not earned yet'?></span><h2><?=e($name)?></h2><p><?=e($rule)?></p></article><?php endforeach;?></div>
